from pysat.solvers import Solver
from pysat.card import CardEnc, EncType

def edge_var(i,j,n):
    if i>j: i,j=j,i
    # 1-based index over pairs lex
    # compute count pairs before i: i*n - i*(i+1)//2? pairs (a,b) a<b, a<i: sum_{a=0}^{i-1} (n-1-a) = i*(n-1)-i*(i-1)//2
    return i*(n-1)-i*(i-1)//2 + (j-i)  # 1..C(n,2)

def girth_cycles(edges,n):
    adj=[set() for _ in range(n)]
    for i,j in edges:
        adj[i].add(j); adj[j].add(i)
    # find all cycles 3..6 simple maybe return one
    for L in range(3,7):
        # DFS canonical start min vertex in cycle, second < last to avoid dup
        path=[]
        def dfs(start,cur,depth):
            if depth==L:
                if start in adj[cur]:
                    cyc=path[:]
                    # start is min by construction; avoid reverse dup
                    if cyc[1] < cyc[-1]:
                        return cyc
                return None
            for nb in adj[cur]:
                if nb<=start: continue
                if nb in path: continue
                path.append(nb)
                r=dfs(start,nb,depth+1)
                if r: return r
                path.pop()
            return None
        for s in range(n):
            path=[s]
            r=dfs(s,s,1)
            if r: return r
    return None

def solve_partition(sizes, upto=100000):
    n=19
    cols=[]
    for c,sz in enumerate(sizes): cols += [c]*sz
    allowed=[]
    for i in range(n):
        for j in range(i+1,n):
            if cols[i]!=cols[j]: allowed.append((i,j))
    maxvar=n*(n-1)//2
    cnf=[]
    # disallow within color as unit negatives
    for i in range(n):
        for j in range(i+1,n):
            if cols[i]==cols[j]: cnf.append([-edge_var(i,j,n)])
    # cardinality >= 32 on allowed
    lits=[edge_var(i,j,n) for i,j in allowed]
    card=CardEnc.atleast(lits=lits, bound=32, top_id=maxvar, encoding=EncType.totalizer)
    cnf.extend(card.clauses); top=card.nv
    # add all cycle constraints? Generate subsets and cyclic orders canonical
    # Let's add triangles and C4 upfront via combinations of vertices and check cycles in allowed complete colored graph.
    cyc_count=0
    # Generate all simple cycles canonical in allowed supergraph length 3..6. To avoid huge maybe do DFS on supergraph.
    sup=[set() for _ in range(n)]
    for i,j in allowed: sup[i].add(j); sup[j].add(i)
    clauses=[]
    for L in range(3,7):
        for s in range(n):
            path=[s]
            def dfs(cur,depth):
                nonlocal cyc_count
                if depth==L:
                    if s in sup[cur] and path[1] < path[-1]:
                        clauses.append([-edge_var(path[t], path[(t+1)%L], n) for t in range(L)])
                        cyc_count += 1
                    return
                for nb in sup[cur]:
                    if nb<=s: continue
                    if nb in path: continue
                    path.append(nb)
                    dfs(nb,depth+1)
                    path.pop()
            dfs(s,1)
    cnf.extend(clauses)
    print('partition',sizes,'allowed',len(allowed),'cycleclauses',cyc_count,'total clauses',len(cnf),'top',top, flush=True)
    with Solver(name='glucose4', bootstrap_with=cnf) as sol:
        ok=sol.solve()
        print(' solved',ok, flush=True)
        if ok:
            model=set(l for l in sol.get_model() if l>0)
            edges=[(i,j) for i,j in allowed if edge_var(i,j,n) in model]
            print('edges',len(edges),'cycle?',girth_cycles(edges,n),'degrees',[sum(1 for e in edges if v in e) for v in range(n)])
            return edges
    return None

